actions.command:
cat << 'EOF' > main.go
package main

import (
	"bytes"
	"flag"
	"fmt"
	"go/ast"
	"go/format"
	"go/parser"
	"go/token"
	"io/fs"
	"log"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"

	"golang.org/x/tools/imports"
)

const (
	versionStr = "3.0.0-20260611193416-a37f51062178"
	builtWith  = "go1.26.0"
	tagStr     = "v3.0.0-20260611193416-a37f51062178"
	commitStr  = "n/a"
	sourceStr  = "github.com/incu6us/goimports-reviser/v3"

	groupStd     = "std"
	groupGeneral = "general"
	groupCompany = "company"
	groupProject = "project"
	groupBlanked = "blanked"
	groupDotted  = "dotted"
)

var (
	applyToGeneratedFiles = flag.Bool("apply-to-generated-files", false, "Apply imports sorting and formatting(if the option is set) to generated files. Generated file is a file with first comment which starts with comment '// Code generated'. Optional parameter.")
	companyPrefixes       = flag.String("company-prefixes", "", "Company package prefixes which will be placed after 3rd-party group by default(if defined). Values should be comma-separated. Optional parameters.")
	excludes              = flag.String("excludes", "", "Exclude files or dirs, example: '.git/,proto/*.go'.")
	filePath              = flag.String("file-path", "", "Deprecated. Put file name as an argument(last item) of command line.")
	formatOption          = flag.Bool("format", false, "Option will perform additional formatting. Optional parameter.")
	importsOrder          = flag.String("imports-order", "std,general,company,project", "Your imports groups can be sorted in your way. \nstd - std import group; \ngeneral - libs for general purpose; \ncompany - inter-org or your company libs(if you set '-company-prefixes'-option, then 4th group will be split separately. In other case, it will be the part of general purpose libs); \nproject - your local project dependencies;\nblanked - imports with \"_\" alias;\ndotted - imports with \".\" alias.\nOptional parameter.")
	listDiff              = flag.Bool("list-diff", false, "Option will list files whose formatting differs from goimports-reviser. Optional parameter.")
	localOption           = flag.String("local", "", "Deprecated")
	outputOption          = flag.String("output", "file", "Can be \"file\", \"write\" or \"stdout\". Whether to write the formatted content back to the file or to stdout. When \"write\" together with \"-list-diff\" will list the file name and write back to the file. Optional parameter.")
	projectName           = flag.String("project-name", "", "Your project name(ex.: github.com/incu6us/goimports-reviser). Optional parameter.")
	recursive             = flag.Bool("recursive", false, "Apply rules recursively if target is a directory. In case of ./... execution will be recursively applied by default. Optional parameter.")
	rmUnused              = flag.Bool("rm-unused", false, "Remove unused imports. Optional parameter.")
	separateNamed         = flag.Bool("separate-named", false, "Option will separate named imports from the rest of the imports, per group. Optional parameter.")
	setAlias              = flag.Bool("set-alias", false, "Set alias for versioned package names, like 'github.com/go-pg/pg/v9'. In this case import will be set as 'pg \"github.com/go-pg/pg/v9\"'. Optional parameter.")
	setExitStatus         = flag.Bool("set-exit-status", false, "set the exit status to 1 if a change is needed/made. Optional parameter.")
	useCache              = flag.Bool("use-cache", false, "Use cache to improve performance. Optional parameter.")
	version               = flag.Bool("version", false, "Show version information")
	versionOnly           = flag.Bool("version-only", false, "Show only the version string")
)

func main() {
	log.SetFlags(log.LstdFlags)
	log.SetOutput(os.Stderr)

	flag.Parse()

	if *versionOnly {
		fmt.Println(versionStr)
		os.Exit(0)
	}

	if *version {
		fmt.Printf("version: %s\nbuilt with: %s\ntag: %s\ncommit: %s\nsource: %s\n", versionStr, builtWith, tagStr, commitStr, sourceStr)
		os.Exit(0)
	}

	args := flag.Args()
	var paths []string
	for _, a := range args {
		paths = append(paths, a)
	}
	if *filePath != "" {
		found := false
		for _, p := range paths {
			if p == *filePath {
				found = true
				break
			}
		}
		if !found {
			paths = append(paths, *filePath)
		}
	}

	if len(paths) == 0 {
		flag.Usage()
		log.Fatalf("no file(s) or directory(ies) specified on input")
	}

	// Validate imports order
	orderGroups := strings.Split(*importsOrder, ",")
	validGroups := map[string]bool{
		groupStd:     true,
		groupGeneral: true,
		groupCompany: true,
		groupProject: true,
		groupBlanked: true,
		groupDotted:  true,
	}
	hasStd, hasGen, hasComp, hasProj := false, false, false, false
	for _, g := range orderGroups {
		g = strings.TrimSpace(g)
		if !validGroups[g] {
			flag.Usage()
			log.Fatalf("unknown order group type: %q", g)
		}
		if g == groupStd {
			hasStd = true
		}
		if g == groupGeneral {
			hasGen = true
		}
		if g == groupCompany {
			hasComp = true
		}
		if g == groupProject {
			hasProj = true
		}
	}
	if !hasStd || !hasGen || !hasComp || !hasProj {
		flag.Usage()
		log.Fatalf("use default at least 4 parameters to sort groups of your imports: %q", "std,general,company,project")
	}

	log.Printf("Paths: %v\n", paths)

	hasError := false
	hasChanges := false

	var excludeList []string
	if *excludes != "" {
		for _, e := range strings.Split(*excludes, ",") {
			e = strings.TrimSpace(e)
			if e != "" {
				excludeList = append(excludeList, e)
			}
		}
	}

	for _, p := range paths {
		log.Printf("Processing %s\n", p)
		files, err := resolveFiles(p, *recursive, excludeList)
		if err != nil {
			log.Printf("Failed to resolve files for %s: %v\n", p, err)
			hasError = true
			continue
		}

		for _, file := range files {
			changed, err := processFile(file, orderGroups, excludeList)
			if err != nil {
				if strings.HasPrefix(err.Error(), "Could not determine project name") {
					flag.Usage()
					log.Printf("%v\n", err)
					os.Exit(1)
				}
				log.Printf("%v\n", err)
				hasError = true
			}
			if changed {
				hasChanges = true
			}
		}
	}

	if *filePath != "" {
		log.Println("-file-path is deprecated. Put file name(s) as last argument to the command(Example: goimports-reviser -rm-unused -set-alias -format goimports-reviser/main.go)")
		log.Println("All changes to file are applied, but command-line syntax should be fixed")
		hasError = true
	}

	if *localOption != "" {
		log.Println("-local is deprecated and will be removed soon. Use -company-prefixes instead.")
		log.Println("All changes to file are applied, but command-line syntax should be fixed")
		hasError = true
	}

	if (*setExitStatus && hasChanges) || hasError {
		os.Exit(1)
	}
}

func resolveFiles(path string, isRecursive bool, excludeList []string) ([]string, error) {
	if path == "./..." {
		return walkDir(".", true, excludeList)
	}
	fi, err := os.Stat(path)
	if err != nil {
		// file doesn't exist
		return []string{path}, nil
	}
	if !fi.IsDir() {
		return []string{path}, nil
	}
	return walkDir(path, isRecursive, excludeList)
}

func isExcluded(relPath, baseName string, excludeList []string) bool {
	for _, excl := range excludeList {
		exclTrim := strings.TrimSuffix(excl, "/")
		if match, _ := filepath.Match(excl, baseName); match {
			return true
		}
		if match, _ := filepath.Match(exclTrim, baseName); match {
			return true
		}
		if match, _ := filepath.Match(excl, relPath); match {
			return true
		}
		if strings.Contains(relPath, excl) || strings.Contains(relPath, exclTrim) {
			return true
		}
	}
	return false
}

func walkDir(root string, isRecursive bool, excludeList []string) ([]string, error) {
	var result []string
	if isRecursive {
		err := filepath.WalkDir(root, func(p string, d fs.DirEntry, err error) error {
			if err != nil {
				return err
			}
			name := d.Name()
			if d.IsDir() {
				if p != root && (strings.HasPrefix(name, ".") || isExcluded(p, name, excludeList)) {
					return filepath.SkipDir
				}
				return nil
			}
			if strings.HasSuffix(name, ".go") && !strings.HasPrefix(name, ".") {
				if !isExcluded(p, name, excludeList) {
					result = append(result, p)
				}
			}
			return nil
		})
		return result, err
	} else {
		entries, err := os.ReadDir(root)
		if err != nil {
			return nil, err
		}
		for _, entry := range entries {
			name := entry.Name()
			if !entry.IsDir() && strings.HasSuffix(name, ".go") && !strings.HasPrefix(name, ".") {
				p := filepath.Join(root, name)
				if !isExcluded(p, name, excludeList) {
					result = append(result, p)
				}
			}
		}
		return result, nil
	}
}

func findProjectName(filePath string) (string, error) {
	if *projectName != "" {
		return *projectName, nil
	}
	absPath, err := filepath.Abs(filePath)
	if err != nil {
		absPath = filePath
	}
	dir := filepath.Dir(absPath)
	for {
		goModPath := filepath.Join(dir, "go.mod")
		data, err := os.ReadFile(goModPath)
		if err == nil {
			lines := strings.Split(string(data), "\n")
			for _, line := range lines {
				line = strings.TrimSpace(line)
				if strings.HasPrefix(line, "module ") {
					mod := strings.TrimSpace(strings.TrimPrefix(line, "module "))
					return mod, nil
				}
			}
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			break
		}
		dir = parent
	}
	return "", fmt.Errorf("Could not determine project name for path %s: open go.mod: no such file or directory", filePath)
}

var genCommentRegex = regexp.MustCompile(`^//\s*Code generated.*DO NOT EDIT\.$`)

func isGeneratedFile(content []byte) bool {
	lines := strings.Split(string(content), "\n")
	for _, line := range lines {
		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}
		if strings.HasPrefix(line, "//") || strings.HasPrefix(line, "/*") {
			if genCommentRegex.MatchString(line) {
				return true
			}
		} else {
			break
		}
	}
	return false
}

type importSpecInfo struct {
	Alias   string // "" if no explicit alias in source
	Path    string // quoted, e.g. "fmt"
	Clean   string // unquoted, e.g. fmt
	Comment string // inline comment
}

func processFile(file string, orderGroups []string, excludeList []string) (bool, error) {
	content, err := os.ReadFile(file)
	if err != nil {
		return false, fmt.Errorf("Failed to fix file: open %s: no such file or directory", file)
	}

	if !*applyToGeneratedFiles && isGeneratedFile(content) {
		if *outputOption == "stdout" {
			os.Stdout.Write(content)
		}
		return false, nil
	}

	projName, err := findProjectName(file)
	if err != nil {
		return false, err
	}

	if *rmUnused {
		out, err := imports.Process(file, content, &imports.Options{
			Comments:  true,
			TabIndent: true,
			TabWidth:  8,
		})
		if err != nil {
			return false, fmt.Errorf("Failed to fix file: %v", err)
		}
		content = out
	}

	fset := token.NewFileSet()
	astFile, err := parser.ParseFile(fset, file, content, parser.ParseComments)
	if err != nil {
		return false, fmt.Errorf("Failed to fix file: file has invalid Go source content, use -excludes flag to skip this file: %v", err)
	}

	formattedContent, err := reviseImports(fset, astFile, content, projName, orderGroups)
	if err != nil {
		return false, fmt.Errorf("Failed to fix file: %v", err)
	}

	if *formatOption {
		formattedContent, err = applyFormat(formattedContent)
		if err != nil {
			return false, fmt.Errorf("Failed to fix file: %v", err)
		}
	}

	isChanged := !bytes.Equal(content, formattedContent)

	if *outputOption == "stdout" {
		if *listDiff && isChanged {
			fmt.Println(file)
		} else {
			os.Stdout.Write(formattedContent)
		}
	} else if *outputOption == "write" {
		if *listDiff && isChanged {
			fmt.Println(file)
		}
		if isChanged {
			if err := os.WriteFile(file, formattedContent, 0644); err != nil {
				return isChanged, fmt.Errorf("Failed to write file %s: %v", file, err)
			}
		}
	} else { // "file"
		if *listDiff {
			if isChanged {
				fmt.Println(file)
			}
		} else {
			if isChanged {
				if err := os.WriteFile(file, formattedContent, 0644); err != nil {
					return isChanged, fmt.Errorf("Failed to write file %s: %v", file, err)
				}
			}
		}
	}

	return isChanged, nil
}

func isStdPackage(path string) bool {
	firstPart := path
	if idx := strings.Index(path, "/"); idx != -1 {
		firstPart = path[:idx]
	}
	return !strings.Contains(firstPart, ".")
}

func isProjectPackage(path, projName string) bool {
	if projName == "" {
		return false
	}
	return path == projName || strings.HasPrefix(path, projName+"/")
}

func isCompanyPackage(path string, companyList []string) bool {
	for _, c := range companyList {
		if c != "" && (path == c || strings.HasPrefix(path, c+"/")) {
			return true
		}
	}
	return false
}

func reviseImports(fset *token.FileSet, astFile *ast.File, origContent []byte, projName string, orderGroups []string) ([]byte, error) {
	var compList []string
	if *companyPrefixes != "" {
		for _, c := range strings.Split(*companyPrefixes, ",") {
			c = strings.TrimSpace(c)
			if c != "" {
				compList = append(compList, c)
			}
		}
	}

	var specs []importSpecInfo
	type lineComment struct {
		line    int
		comment string
	}
	var comments []lineComment
	for _, cg := range astFile.Comments {
		for _, c := range cg.List {
			line := fset.Position(c.Pos()).Line
			comments = append(comments, lineComment{line: line, comment: c.Text})
		}
	}

	for _, decl := range astFile.Decls {
		genDecl, ok := decl.(*ast.GenDecl)
		if !ok || genDecl.Tok != token.IMPORT {
			continue
		}
		for _, spec := range genDecl.Specs {
			imp, ok := spec.(*ast.ImportSpec)
			if !ok {
				continue
			}
			cleanPath := strings.Trim(imp.Path.Value, `"`)
			alias := ""
			if imp.Name != nil {
				alias = imp.Name.Name
			}

			if *setAlias && alias == "" {
				if idx := strings.LastIndex(cleanPath, "/v"); idx != -1 {
					versionPart := cleanPath[idx+2:]
					isVer := true
					for _, ch := range versionPart {
						if ch < '0' || ch > '9' {
							isVer = false; break
						}
					}
					if isVer && len(versionPart) > 0 {
						base := cleanPath[:idx]
						alias = getPackageBaseName(base)
					}
				}
			}

			// find inline comment
			specLine := fset.Position(imp.Pos()).Line
			comment := ""
			for _, c := range comments {
				if c.line == specLine {
					comment = c.comment
					break
				}
			}

			specs = append(specs, importSpecInfo{
				Alias:   alias,
				Path:    imp.Path.Value,
				Clean:   cleanPath,
				Comment: comment,
			})
		}
	}

	// Classify specs into orderGroups
	groupedSpecs := make(map[string][]importSpecInfo)
	hasBlankedGroup := false
	hasDottedGroup := false
	for _, g := range orderGroups {
		if g == groupBlanked {
			hasBlankedGroup = true
		}
		if g == groupDotted {
			hasDottedGroup = true
		}
	}

	for _, sp := range specs {
		grp := ""
		if sp.Alias == "_" && hasBlankedGroup {
			grp = groupBlanked
		} else if sp.Alias == "." && hasDottedGroup {
			grp = groupDotted
		} else if isStdPackage(sp.Clean) {
			grp = groupStd
		} else if isProjectPackage(sp.Clean, projName) {
			grp = groupProject
		} else if isCompanyPackage(sp.Clean, compList) {
			grp = groupCompany
		} else {
			grp = groupGeneral
		}
		groupedSpecs[grp] = append(groupedSpecs[grp], sp)
	}

	// Build the new import block string
	var importLines []string
	for _, grpName := range orderGroups {
		groupList, ok := groupedSpecs[grpName]
		if !ok || len(groupList) == 0 {
			continue
		}

		if *separateNamed {
			var unnamed []importSpecInfo
			var named []importSpecInfo
			for _, sp := range groupList {
				if sp.Alias == "" {
					unnamed = append(unnamed, sp)
				} else {
					named = append(named, sp)
				}
			}
			sortSpecs(unnamed)
			sortSpecs(named)

			var lines []string
			for _, sp := range unnamed {
				lines = append(lines, formatImportSpec(sp))
			}
			if len(unnamed) > 0 && len(named) > 0 {
				lines = append(lines, "")
			}
			for _, sp := range named {
				lines = append(lines, formatImportSpec(sp))
			}
			if len(importLines) > 0 {
				importLines = append(importLines, "")
			}
			importLines = append(importLines, lines...)
		} else {
			sortSpecs(groupList)
			var lines []string
			for _, sp := range groupList {
				lines = append(lines, formatImportSpec(sp))
			}
			if len(importLines) > 0 {
				importLines = append(importLines, "")
			}
			importLines = append(importLines, lines...)
		}
	}

	// Reconstruct code
	src := string(origContent)
	var newImportBlock string
	if len(specs) == 0 {
		newImportBlock = ""
	} else if len(specs) == 1 && len(importLines) == 1 && !*separateNamed {
		newImportBlock = fmt.Sprintf("import %s", importLines[0])
	} else {
		var buf bytes.Buffer
		buf.WriteString("import (\n")
		for _, l := range importLines {
			if l == "" {
				buf.WriteString("\n")
			} else {
				buf.WriteString("\t" + l + "\n")
			}
		}
		buf.WriteString(")")
		newImportBlock = buf.String()
	}

	// Replace imports in source code
	cleanSrc := removeImportDecls(astFile, fset, src, newImportBlock)

	formatted, err := format.Source([]byte(cleanSrc))
	if err != nil {
		return origContent, err
	}
	return formatted, nil
}

func getPackageBaseName(path string) string {
	if idx := strings.LastIndex(path, "/"); idx != -1 {
		return path[idx+1:]
	}
	return path
}

func sortSpecs(specs []importSpecInfo) {
	sort.Slice(specs, func(i, j int) bool {
		return specs[i].Clean < specs[j].Clean
	})
}

func formatImportSpec(sp importSpecInfo) string {
	s := ""
	if sp.Alias != "" {
		s = sp.Alias + " " + sp.Path
	} else {
		s = sp.Path
	}
	if sp.Comment != "" {
		s = s + " " + sp.Comment
	}
	return s
}

func removeImportDecls(astFile *ast.File, fset *token.FileSet, src string, newImportBlock string) string {
	if len(astFile.Decls) == 0 {
		return src
	}

	firstImportPos := token.NoPos
	lastImportEnd := token.NoPos

	for _, decl := range astFile.Decls {
		genDecl, ok := decl.(*ast.GenDecl)
		if ok && genDecl.Tok == token.IMPORT {
			if firstImportPos == token.NoPos || genDecl.Pos() < firstImportPos {
				firstImportPos = genDecl.Pos()
			}
			if lastImportEnd == token.NoPos || genDecl.End() > lastImportEnd {
				lastImportEnd = genDecl.End()
			}
		}
	}

	if firstImportPos == token.NoPos {
		// No imports found originally
		if newImportBlock == "" {
			return src
		}
		// Insert imports after package statement
		pkgLineEnd := fset.Position(astFile.Name.End()).Offset
		// find newline after package
		for pkgLineEnd < len(src) && src[pkgLineEnd] != '\n' {
			pkgLineEnd++
		}
		return src[:pkgLineEnd] + "\n\n" + newImportBlock + src[pkgLineEnd:]
	}

	startOffset := fset.Position(firstImportPos).Offset
	endOffset := fset.Position(lastImportEnd).Offset

	if newImportBlock == "" {
		// Remove imports and trailing empty lines
		for endOffset < len(src) && (src[endOffset] == '\r' || src[endOffset] == '\n') {
			endOffset++
		}
		return src[:startOffset] + src[endOffset:]
	}

	return src[:startOffset] + newImportBlock + src[endOffset:]
}

func applyFormat(src []byte) ([]byte, error) {
	fset := token.NewFileSet()
	astFile, err := parser.ParseFile(fset, "", src, parser.ParseComments)
	if err != nil {
		return src, err
	}

	var buf bytes.Buffer
	if err := format.Node(&buf, fset, astFile); err != nil {
		return src, err
	}

	lines := strings.Split(buf.String(), "\n")
	var newLines []string
	inHeader := true

	for i := 0; i < len(lines); i++ {
		line := lines[i]
		if inHeader {
			newLines = append(newLines, line)
			if strings.HasPrefix(line, "package ") {
				inHeader = false
			}
			continue
		}

		if strings.HasPrefix(line, "func ") || strings.HasPrefix(line, "type ") || strings.HasPrefix(line, "const ") || strings.HasPrefix(line, "var ") || strings.HasPrefix(line, "//") || strings.HasPrefix(line, "/*") {
			if len(newLines) > 0 && newLines[len(newLines)-1] != "" {
				// check if previous line is package or import or comment belonging to same decl
				prev := newLines[len(newLines)-1]
				if !strings.HasPrefix(prev, "package ") && !strings.HasPrefix(prev, "import ") && prev != ")" {
					newLines = append(newLines, "")
				}
			}
		}
		newLines = append(newLines, line)
	}

	formatted, err := format.Source([]byte(strings.Join(newLines, "\n")))
	if err != nil {
		return src, nil
	}
	return formatted, nil
}
